import React, { useState } from "react";
import api from "../services/api";

export default function ShareCapital() {

  const [id, setId] = useState("3");
  const [data, setData] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const loadBalance = async (e) => {
    e.preventDefault();

    if (!id.trim()) {
      setError("Please enter a member ID.");
      setData(null);
      return;
    }

    try {
      setLoading(true);
      setError("");

      const response = await api.get(`/members/${id.trim()}`);

      setData(response.data);

    } catch (err) {

      console.error("Share capital error:", err);

      setData(null);

      if (err.response?.status === 404) {
        setError("Member not found.");
      } else if (err.response?.status === 401) {
        setError("Unauthorized. Please login again.");
      } else {
        setError("Unable to load share capital.");
      }

    } finally {
      setLoading(false);
    }
  };

  return (
      <>
        {/* PAGE HEADER */}
        <div className="page-head">
          <div>
          <span className="eyebrow">
            COOPERATIVE EQUITY
          </span>

            <h2>
              Share Capital
            </h2>

            <p>
              Check a member's share capital balance.
            </p>
          </div>
        </div>

        {/* SEARCH FORM */}
        <form
            className="inline-form"
            onSubmit={loadBalance}
        >
          <input
              type="text"
              value={id}
              onChange={(e) => setId(e.target.value)}
              placeholder="Enter Member ID (e.g. 3)"
          />

          <button
              type="submit"
              className="primary"
              disabled={loading}
          >
            {loading ? "Loading..." : "Check balance"}
          </button>
        </form>

        {/* ERROR */}
        {error && (
            <div className="alert">
              {error}
            </div>
        )}

        {/* SHARE CAPITAL CARD */}
        {data && (
            <div className="share-capital-card">

              {/* LEFT SIDE */}
              <div className="share-left">

                <div className="rupee-icon">
                  ₹
                </div>

                <div className="member-details">

              <span className="member-id">
                {data.memberId || `FPO-${data.id}`}
              </span>

                  <h3>
                    {data.name || "-"}
                  </h3>

                  <p>
                    Current share capital
                  </p>

                </div>

              </div>

              {/* RIGHT SIDE */}
              <div className="share-amount">

            <span>
              Share Capital
            </span>

                <strong>
                  ₹{data.shareCapital || 0}
                </strong>

              </div>

            </div>
        )}
      </>
  );
}
